			JDefinedClass grandParentClass = (JDefinedClass) grandParent;

			writeSummary("\tMoving inner class " + clazz.fullName() + " to class " + grandParentClass.fullName());

			classes = getPrivateField(grandParentClass, "classes");

			// Update the class's outer reference to the grandparent class
			setPrivateField(clazz, "outer", grandParentClass);
		}
		else {
			JPackage grandParentPackage = (JPackage) grandParent;

			writeSummary("\tMoving inner class " + clazz.fullName() + " to package " + grandParentPackage.name());

			classes = getPrivateField(grandParentPackage, "classes");

			// In this scenario class should have "static" modifier reset otherwise it won't compile:
			setPrivateField(clazz.mods(), "mods", Integer.valueOf(clazz.mods().getValue() & ~JMod.STATIC));

			for (ClassOutline classOutline : outline.getClasses()) {
				if (classOutline.implClass == clazz) {
					XSComponent sc = classOutline.target.getSchemaComponent();

					// FIXME: Inner class is always a local declaration.
					assert (sc instanceof XSDeclaration && ((XSDeclaration) sc).isLocal());

					setPrivateField(sc, "anonymous", Boolean.FALSE);

					break;
				}
			}

			// Update the class's outer reference to null since it's now in a package
			setPrivateField(clazz, "outer", null);
		}

		if (classes.containsKey(clazz.name())) {
			writeSummary("\tRenaming class " + clazz.fullName() + " to class " + parent.name() + clazz.name());
			setPrivateField(clazz, "name", parent.name() + clazz.name());
		}

		classes.put(clazz.name(), clazz);
	}
