            position.setTime(new Date(buf.readUnsignedInt() * 1000));

            position.setValid(true);
            position.setLongitude(buf.readInt() / 10000000.0);
            position.setLatitude(buf.readInt() / 10000000.0);

            if (buf.readUnsignedByte() == 2) {
